// ============================================================================
// chi_mesh_soc_nodirect_test_pkg -- tests generated by socgen from socgen/specs/chi_mesh_soc.yaml
//   chi_mesh_soc_nodirect_smoke_test         every master: write + read on every NoC port,
//                                   ID read of the first APB slot, DECERR hole
//   chi_mesh_soc_nodirect_ral_test           RAL reset values, then write/read of every
//                                   testable RW register through cpu0
//   chi_mesh_soc_nodirect_path_latency_test  one master at a time, single beats on every
//                                   path; latency must be within ideal + slack
//   chi_mesh_soc_nodirect_traffic_test       every master runs its traffic profile at once
//   chi_mesh_soc_nodirect_scenario_test      +SCENARIO=<name>: the scenario's masters only
//   chi_mesh_soc_nodirect_coherence_test     CHI: false sharing, dirty lines migrating between
//                                   caches and AMBA masters, producer / consumer
// Plusargs: +SOC_ITEMS=<n> bursts per master (default 50), +SOC_TIMING=0|1|2,
// +SOC_LAT_STRICT (a missed latency_target is an error), +VCD.
// ============================================================================
`ifndef CHI_MESH_SOC_NODIRECT_TEST_PKG_SV
`define CHI_MESH_SOC_NODIRECT_TEST_PKG_SV
package chi_mesh_soc_nodirect_test_pkg;
  import uvm_pkg::*;
  `include "uvm_macros.svh"
  import axi4_pkg::*;
  import chi_mesh_soc_nodirect_pkg::*;
  import chi_mesh_soc_nodirect_ral_pkg::*;
  import chi_mesh_soc_nodirect_env_pkg::*;

  // one master's traffic over its windows
  class chi_mesh_soc_nodirect_traffic_seq extends uvm_sequence #(axi4_item);
    `uvm_object_utils(chi_mesh_soc_nodirect_traffic_seq)
    int mi, scn = -1, items = 50;
    window_t w [$];
    int unsigned cursor [$];        // linear / block2d progress per window
    bit pace_all;                   // +SOC_PACE: pace every profile that has bandwidth_mbps

    function new(string name = "chi_mesh_soc_nodirect_traffic_seq");
      super.new(name);
    endfunction

    function axi4_item next(int k);
      window_t x = w[k];
      axi4_item t = axi4_item::type_id::create("t");
      int unsigned beats, room;
      logic [31:0] a;
      t.write = ($urandom_range(99, 0) >= x.read_pct);
      t.id = $urandom_range((1 << ID_WIDTH) - 1, 0);
      t.size = 3'd2; t.burst = AXI4_INCR;
      beats = $urandom_range(x.beats_hi, x.beats_lo);
      if (x.apb) begin                    // ID read of a random mapped slot
        int s = $urandom_range(APB_NMAPPED - 1, 0);
        t.write = 0; t.addr = APB_BASE + (APB_MAPPED_SLOT[s] << 12); t.len = 0;
        t.alloc(); t.strb[0] = 4'hF;
        return t;
      end
      case (x.pattern)
        PAT_LINEAR: begin
          a = x.base + cursor[k];
          room = (4096 - (a & 32'hFFF)) / 4;
          if (beats > room) beats = room;
          cursor[k] = (cursor[k] + beats * 4) % x.size;
        end
        PAT_BLOCK2D: begin               // cursor = line * blk_w + column
          int unsigned line = cursor[k] / x.blk_w, col = cursor[k] % x.blk_w;
          a = x.base + line * x.stride + col;
          room = (x.blk_w - col) / 4;
          if ((4096 - (a & 32'hFFF)) / 4 < room) room = (4096 - (a & 32'hFFF)) / 4;
          if (beats > room) beats = room;
          cursor[k] = (cursor[k] + beats * 4) % (x.blk_w * x.blk_h);
        end
        default: begin
          a = x.base + ($urandom_range(x.size / 4 - 1, 0) * 4);
          room = (4096 - (a & 32'hFFF)) / 4;
          if (beats > room) beats = room;
          if (a + beats * 4 > x.base + x.size) beats = (x.base + x.size - a) / 4;
        end
      endcase
      if (beats == 0) beats = 1;
      t.addr = a; t.len = beats - 1;
      t.alloc();
      foreach (t.data[i]) begin t.data[i] = $urandom; t.strb[i] = 4'hF; end
      return t;
    endfunction

    task body();
      get_windows(scn, mi, w);
      if (w.size() == 0) return;
      foreach (w[i]) cursor.push_back(0);
      pace_all = $test$plusargs("SOC_PACE");
      repeat (items) begin
        int k = $urandom_range(w.size() - 1, 0);
        axi4_item t = next(k);
        realtime t0 = $realtime;
        start_item(t);
        finish_item(t);
        if ((w[k].pace || pace_all) && w[k].bw_mbps && !w[k].apb) begin
          // start-to-start spacing for this burst at the requested rate:
          // bytes / (MB/s) = bytes * 1000 / bw ns
          realtime due = t0 + (real'((t.len + 1) * 4) * 1000.0 / real'(w[k].bw_mbps)) * 1ns;
          if ($realtime < due) #(due - $realtime);
        end
        else if (w[k].gap) #(w[k].gap * TCK * 1ns);
      end
    endtask
  endclass

  // ==========================================================================
  class chi_mesh_soc_nodirect_base_test extends uvm_test;
    `uvm_component_utils(chi_mesh_soc_nodirect_base_test)
    chi_mesh_soc_nodirect_env     env;
    chi_mesh_soc_nodirect_env_cfg cfg;
    int items = 50;

    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction

    function void build_phase(uvm_phase phase);
      int timing = 1;
      super.build_phase(phase);
      void'($value$plusargs("SOC_ITEMS=%d", items));
      void'($value$plusargs("SOC_TIMING=%d", timing));
      cfg = chi_mesh_soc_nodirect_env_cfg::type_id::create("cfg");
      cfg.set_timing(timing);
      cfg.lat_strict = $test$plusargs("SOC_LAT_STRICT");
      configure(cfg);
      uvm_config_db#(chi_mesh_soc_nodirect_env_cfg)::set(this, "env", "cfg", cfg);
      env = chi_mesh_soc_nodirect_env::type_id::create("env", this);
    endfunction

    virtual function void configure(chi_mesh_soc_nodirect_env_cfg c);
    endfunction

    function void end_of_elaboration_phase(uvm_phase phase);
      uvm_root::get().set_timeout(100ms, 1);
    endfunction

    task run_phase(uvm_phase phase);
      phase.raise_objection(this);
      #(20 * TCK * 1ns);
      body();
      #(50 * TCK * 1ns);
      phase.drop_objection(this);
    endtask

    virtual task body();
    endtask

    // single-beat accesses; the scoreboard checks the responses and data
    task wr(int mi, logic [31:0] a, bit [31:0] d);
      axi4_resp_e r;
      axi4_api::write32(env.m_agent[mi].sqr, a, d, r);
    endtask
    task rd(int mi, logic [31:0] a);
      axi4_resp_e r;
      bit [31:0] d;
      axi4_api::read32(env.m_agent[mi].sqr, a, d, r);
    endtask
    task wr_rd(int mi, logic [31:0] a);
      wr(mi, a, $urandom);
      rd(mi, a);
    endtask

    function bit vip_master(int mi);
      return env.m_agent[mi].sqr != null;
    endfunction
  endclass

  // ==========================================================================
  class chi_mesh_soc_nodirect_smoke_test extends chi_mesh_soc_nodirect_base_test;
    `uvm_component_utils(chi_mesh_soc_nodirect_smoke_test)
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    task body();
      for (int i = 0; i < NM; i++) if (vip_master(i)) spawn(i);
      wait fork;
    endtask
    task automatic spawn(int i);
      fork
        automatic int mi = i;
        begin
          for (int si = 0; si < NS; si++) begin
            if (S_KIND[si] == "apb_bridge") rd(mi, PATH_ADDR[mi][si]);
            else wr_rd(mi, PATH_ADDR[mi][si]);
          end
          if (HAS_UNMAPPED) rd(mi, UNMAPPED_ADDR);
        end
      join_none
    endtask
  endclass

  // ==========================================================================
  class chi_mesh_soc_nodirect_ral_test extends chi_mesh_soc_nodirect_base_test;
    `uvm_component_utils(chi_mesh_soc_nodirect_ral_test)
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    task body();
      uvm_reg_hw_reset_seq rst = uvm_reg_hw_reset_seq::type_id::create("rst");
      uvm_reg regs[$];
      uvm_status_e st;
      int n = 0;
      rst.model = env.regmodel;
      rst.start(null);
      env.regmodel.get_registers(regs);
      foreach (regs[i]) begin
        uvm_reg_field f[$];
        bit rw = 1;
        if (uvm_resource_db#(bit)::get_by_name({"REG::", regs[i].get_full_name()}, "NO_REG_TESTS", 0) != null) continue;
        regs[i].get_fields(f);
        foreach (f[j]) if (f[j].get_access() != "RW") rw = 0;
        if (!rw) continue;
        repeat (2) begin
          uvm_reg_data_t v = {$urandom, $urandom};
          regs[i].write(st, v);
          if (st != UVM_IS_OK) `uvm_error("RAL", {regs[i].get_full_name(), ": write failed"})
          regs[i].mirror(st, UVM_CHECK);
          n++;
        end
      end
      `uvm_info("RAL", $sformatf("reset values checked on %0d registers, %0d write/read checks",
                regs.size(), n), UVM_LOW)
      $display("RAL_PASS regs=%0d rw_checks=%0d", regs.size(), n);
    endtask
  endclass

  // ==========================================================================
  class chi_mesh_soc_nodirect_path_latency_test extends chi_mesh_soc_nodirect_base_test;
    `uvm_component_utils(chi_mesh_soc_nodirect_path_latency_test)
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    function void configure(chi_mesh_soc_nodirect_env_cfg c);
      c.set_timing(0);
      c.zero_load_check = 1;
    endfunction
    task body();
      for (int mi = 0; mi < NM; mi++) begin
        if (!vip_master(mi)) continue;
        for (int si = 0; si < NS; si++) begin
          if (S_KIND[si] == "apb_bridge") begin
            rd(mi, PATH_ADDR[mi][si]);
            wr(mi, PATH_ADDR[mi][si] + 32'h10, $urandom);
          end else wr_rd(mi, PATH_ADDR[mi][si]);
        end
      end
    endtask
  endclass

  // ==========================================================================
  class chi_mesh_soc_nodirect_traffic_test extends chi_mesh_soc_nodirect_base_test;
    `uvm_component_utils(chi_mesh_soc_nodirect_traffic_test)
    int scn = -1;
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    task body();
      for (int i = 0; i < NM; i++) if (vip_master(i)) spawn(i);
      wait fork;
    endtask
    task automatic spawn(int mi);
      chi_mesh_soc_nodirect_traffic_seq s = chi_mesh_soc_nodirect_traffic_seq::type_id::create($sformatf("traffic_%s", M_NAME[mi]));
      s.mi = mi; s.scn = scn; s.items = items;
      fork
        automatic chi_mesh_soc_nodirect_traffic_seq sq = s;
        automatic int k = mi;
        sq.start(env.m_agent[k].sqr);
      join_none
    endtask
  endclass

  class chi_mesh_soc_nodirect_scenario_test extends chi_mesh_soc_nodirect_traffic_test;
    `uvm_component_utils(chi_mesh_soc_nodirect_scenario_test)
    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction
    task body();
      string name;
      if (!$value$plusargs("SCENARIO=%s", name)) `uvm_fatal("SCN", "+SCENARIO=<name> required")
      foreach (SCN_NAME[i]) if (N_SCN > 0 && SCN_NAME[i] == name) scn = i;
      if (scn < 0) `uvm_fatal("SCN", {"unknown scenario ", name})
      `uvm_info("SCN", {"scenario ", name}, UVM_LOW)
      super.body();
    endtask
  endclass

  // ==========================================================================
  // Coherence in the memory the HN-F keeps coherent (ddr),
  // every VIP master taking part (CHI RN-Fs through their caches, the others
  // as RN-Is through the home):
  //  1 false sharing: 8 lines, word w of each belongs to participant w % N;
  //    random single-beat writes and reads of own words (a lost update is a
  //    scoreboard error)
  //  2 migration: 8 pairs of lines, each owned by one participant per round
  //    and handed to the next one every round; bursts of 1..16 beats that
  //    may cross the line boundary; the new owner reads the old owner's data
  //  3 producer / consumer for every ordered pair: 16 data words, then a
  //    flag; the consumer polls the flag, checks the data, writes an ack.
  //    The flags race by design and are not scoreboard-checked.
  class chi_mesh_soc_nodirect_coherence_test extends chi_mesh_soc_nodirect_base_test;
    `uvm_component_utils(chi_mesh_soc_nodirect_coherence_test)
    localparam bit [31:0] CB = 32'h80000000;
    localparam bit [31:0] FS = CB, MG = CB + 32'h1000, PC = CB + 32'h2000;
    int pm [$];
    int n_pc_err;

    function new(string name, uvm_component parent);
      super.new(name, parent);
    endfunction

    task rd32(int mi, logic [31:0] a, output bit [31:0] d);
      axi4_resp_e r;
      axi4_api::read32(env.m_agent[mi].sqr, a, d, r);
    endtask

    task automatic burst(int mi, bit wr, logic [31:0] a, int beats);
      axi4_item t = axi4_api::make(wr, a, beats);
      axi4_api::run(env.m_agent[mi].sqr, t);
    endtask

    task automatic false_sharing(int k);
      int np = pm.size();
      repeat (2 * items) begin
        int ln = $urandom_range(7, 0);
        int w = k + np * $urandom_range((16 - 1 - k) / np, 0);
        logic [31:0] a = FS + ln * 64 + w * 4;
        if (w >= 16) continue;
        if ($urandom_range(1, 0)) wr(pm[k], a, $urandom);
        else rd(pm[k], a);
      end
    endtask

    task automatic migrate(int k, int round);
      int np = pm.size();
      for (int p = 0; p < 8; p++) begin
        logic [31:0] base = MG + p * 128;
        if ((p + round) % np != k) continue;
        repeat (4) begin
          int beats = $urandom_range(16, 1);
          int w = $urandom_range(32 - beats, 0);
          burst(pm[k], $urandom_range(1, 0), base + w * 4, beats);
        end
        burst(pm[k], 0, base, 16);         // read both lines
        burst(pm[k], 0, base + 64, 16);
      end
    endtask

    task automatic produce_consume(int p, int c, int it);
      bit [31:0] d;
      int n;
      for (int k = 0; k < 16; k++) wr(p, PC + k * 4, {8'(it), 8'(p), 8'(c), 8'(k)});
      wr(p, PC + 32'h40, it);
      fork
        begin                              // consumer
          n = 0;
          do begin rd32(c, PC + 32'h40, d); n++; end while (d != it && n < 2000);
          if (d != it) begin
            `uvm_error("PC", $sformatf("%s never saw flag %0d from %s", M_NAME[c], it, M_NAME[p]))
            n_pc_err++;
          end
          for (int k = 0; k < 16; k++) begin
            rd32(c, PC + k * 4, d);
            if (d != {8'(it), 8'(p), 8'(c), 8'(k)}) begin
              `uvm_error("PC", $sformatf("%s read word %0d = %08h after flag %0d from %s, expected %08h",
                         M_NAME[c], k, d, it, M_NAME[p], {8'(it), 8'(p), 8'(c), 8'(k)}))
              n_pc_err++;
            end
          end
          wr(c, PC + 32'h80, it);
        end
        begin                              // producer waits for the ack
          bit [31:0] e;
          int m = 0;
          do begin rd32(p, PC + 32'h80, e); m++; end while (e != it && m < 4000);
          if (e != it) begin
            `uvm_error("PC", $sformatf("%s never saw ack %0d from %s", M_NAME[p], it, M_NAME[c]))
            n_pc_err++;
          end
        end
      join
    endtask

    task body();
      int it = 0;
      for (int i = 0; i < NM; i++) if (vip_master(i)) pm.push_back(i);
      env.sb.ign_lo.push_back(PC + 32'h40);
      env.sb.ign_hi.push_back(PC + 32'hC0);
      `uvm_info("COH", $sformatf("%0d participants, phase 1: false sharing", pm.size()), UVM_LOW)
      foreach (pm[k]) fork automatic int kk = k; false_sharing(kk); join_none
      wait fork;
      `uvm_info("COH", "phase 2: migration", UVM_LOW)
      for (int round = 0; round < 2 * pm.size(); round++) begin
        foreach (pm[k]) fork automatic int kk = k; migrate(kk, round); join_none
        wait fork;
      end
      `uvm_info("COH", "phase 3: producer / consumer", UVM_LOW)
      foreach (pm[p]) foreach (pm[c]) if (p != c) begin
        it++;
        produce_consume(pm[p], pm[c], it);
      end
      if (n_pc_err == 0) $display("COH_PASS participants=%0d pairs=%0d", pm.size(), it);
      else $display("COH_FAIL errors=%0d", n_pc_err);
    endtask
  endclass
endpackage
`endif
